from auditchain import (AuditLog, encode_rotation, decode_rotation,
                        encode_signed_root, verify_rotation, SignedRoot)
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey
from cryptography.hazmat.primitives.serialization import Encoding, PublicFormat

seed_a = bytes(range(1,33)); seed_b = bytes(range(33,65))
def pub(s): return Ed25519PrivateKey.from_private_bytes(s).public_key().public_bytes(encoding=Encoding.Raw, format=PublicFormat.Raw)
log = AuditLog()
for r in ("a","b","c","d","e"): log.append(r)
item = log.rotate_signer(seed_a, seed_b)
old, new_key, new, auth = item

MAGIC = b"auditchain/signer-rotation-record/v1\0"
data = encode_rotation(item)

# 1. magic + exact manual layout
def u64(v): return v.to_bytes(8,"big")
def blob(b): return u64(len(b))+b
expected = MAGIC + u64(1) + blob(encode_signed_root(old)) + blob(new_key) + blob(encode_signed_root(new)) + blob(auth)
assert data == expected, "layout mismatch"
print("exact layout OK,", len(data), "bytes")

# 2. roundtrip equality + byte-identical re-encode
rt = decode_rotation(bytes(data))
assert rt == item and isinstance(rt, tuple)
assert encode_rotation(rt) == data
print("roundtrip + re-encode OK")

# 3. error taxonomy
for bad in (None, 1, "x", [], [item], object()):
    try: encode_rotation(bad)
    except TypeError: pass
    else: raise AssertionError("encode non-tuple")
for bad in (None, 1, "x", (), bytearray(data), memoryview(data)):
    try: decode_rotation(bad)
    except TypeError: pass
    else: raise AssertionError("decode non-bytes")
print("type errors OK")

for bad in ((), item[:1], item[:2], item[:3], item + (b"x",)):
    try: encode_rotation(bad)
    except ValueError: pass
    else: raise AssertionError("encode length")

# field width errors at decode
def env(o,k,n,a): return MAGIC+u64(1)+blob(o)+blob(k)+blob(n)+blob(a)
try: decode_rotation(env(encode_signed_root(old), new_key[:-1], encode_signed_root(new), auth))
except ValueError: pass
else: raise AssertionError("key width")
try: decode_rotation(env(encode_signed_root(old), new_key, encode_signed_root(new), auth[:-1]))
except ValueError: pass
else: raise AssertionError("auth width")
# version
try: decode_rotation(MAGIC+u64(2)+data[len(MAGIC)+8:])
except ValueError: pass
else: raise AssertionError("version")
# nested format / oversized length / trailing / truncation
try: decode_rotation(env(b"garbage", new_key, encode_signed_root(new), auth))
except ValueError: pass
else: raise AssertionError("nested")
try: decode_rotation(MAGIC+u64(1)+u64(1<<63)+b"x")
except ValueError: pass
else: raise AssertionError("oversized")
try: decode_rotation(data+b"\x00")
except ValueError: pass
else: raise AssertionError("trailing")
try: decode_rotation(data[:-1])
except ValueError: pass
else: raise AssertionError("truncation")
print("value errors OK")

# 4. valid structure, failed verification still decodes
bogus = (old, new_key, SignedRoot(new.version,new.hash_name,new.size,new.root,new.head,b"\x00"*64), auth)
dec = decode_rotation(encode_rotation(bogus))
assert dec == bogus and verify_rotation(dec, pub(seed_a)) is False
print("decode-with-verify-false OK")

# 5. read-only
h = log.head
encode_rotation(item); decode_rotation(data)
assert log.head == h and len(log) == 5 and log.verify()
print("read-only OK")
print("ALL SPEC CHECKS PASS")
